starter:
module top(input a, b, output y);
  // TODO: implement the circuit described above.
endmodule

solution:
module top(input a, b, output y);
  assign y = a & b;
endmodule

testbench:
`timescale 1ns/1ps
module tb;
reg a,b; wire y; integer i;
top dut(.a(a),.b(b),.y(y));
initial begin
  $dumpfile("dump.vcd"); $dumpvars(0,tb);
  for(i=0;i<4;i=i+1) begin {a,b}=i; #2; if(y !== (a & b)) $fatal(1,"Truth table mismatch"); end
  $display("CHIPLAB_PASS_and-gate");
  $finish;
end
initial begin #10000; $fatal(1,"Testbench timeout"); end
endmodule

