  // TODO: implement the circuit described above.
endmodule

solution:
module top(input [3:0] req, output reg [1:0] index, output valid);
  assign valid=|req;
  always @* begin
    if(req[3]) index=3; else if(req[2]) index=2; else if(req[1]) index=1; else index=0;
  end
endmodule

testbench:
`timescale 1ns/1ps
module tb;
reg [3:0] req; wire [1:0] index; wire valid; reg [1:0] expected; integer i;
top dut(.req(req),.index(index),.valid(valid));
initial begin
  $dumpfile("dump.vcd"); $dumpvars(0,tb);
  for(i=0;i<16;i=i+1) begin req=i; expected=req[3]?3:req[2]?2:req[1]?1:0; #2; if(index!==expected || valid!==( |req)) $fatal(1,"Priority"); end
  $display("CHIPLAB_PASS_priority");
  $finish;
end
initial begin #10000; $fatal(1,"Testbench timeout"); end
endmodule

